// LogiHUR service worker (generated by scripts/build-sw.ts).
const CACHE = "logihur-__VERSION__";
const FILES = __FILES__;

self.addEventListener("install", (event) => {
	event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(FILES)));
});

self.addEventListener("activate", (event) => {
	event.waitUntil(
		caches
			.keys()
			.then((keys) =>
				Promise.all(keys.filter((k) => k.startsWith("logihur-") && k !== CACHE).map((k) => caches.delete(k))),
			)
			.then(() => self.clients.claim()),
	);
});

// the page asks the waiting worker to take over when the user accepts the update
self.addEventListener("message", (event) => {
	if (event.data === "skipWaiting") self.skipWaiting();
});

self.addEventListener("fetch", (event) => {
	const request = event.request;
	if (request.method !== "GET" || new URL(request.url).origin !== self.location.origin) return;
	if (request.mode === "navigate") {
		// the app is a single page: always answer with the cached shell of this version
		event.respondWith(caches.match("./", { cacheName: CACHE }).then((hit) => hit ?? fetch(request)));
		return;
	}
	event.respondWith(
		caches.match(request, { cacheName: CACHE, ignoreSearch: true }).then((hit) => hit ?? fetch(request)),
	);
});
